CREATE TABLE CW_EINVOICE_ARCHIVE (INVOICE_ID BIGINT NOT NULL PRIMARY KEY, FILE_NAME VARCHAR(200) NOT NULL, PDF_DATA BLOB(10485760) NOT NULL, XML_DATA BLOB(5242880) NOT NULL, SHA256 CHAR(64) NOT NULL, ARCHIVED_AT TIMESTAMP NOT NULL, CONSTRAINT CW_EINV_ARCHIVE_FK FOREIGN KEY (INVOICE_ID) REFERENCES CW_INVOICE(ID));
CREATE TABLE CW_INVOICE_CORRECTION (ORIGINAL_INVOICE_ID BIGINT NOT NULL UNIQUE, CORRECTION_INVOICE_ID BIGINT NOT NULL UNIQUE, REASON VARCHAR(1000) NOT NULL, CREATED_AT TIMESTAMP NOT NULL, CONSTRAINT CW_INV_CORR_ORIGINAL_FK FOREIGN KEY (ORIGINAL_INVOICE_ID) REFERENCES CW_INVOICE(ID), CONSTRAINT CW_INV_CORR_NEW_FK FOREIGN KEY (CORRECTION_INVOICE_ID) REFERENCES CW_INVOICE(ID));
